func (_c *ConfigRevisionCreateBulk) OnConflictColumns(columns ...string) *ConfigRevisionUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ConfigRevisionUpsertBulk{
		create: _c,
	}
}

// ConfigRevisionUpsertBulk is the builder for "upsert"-ing
// a bulk of ConfigRevision nodes.
type ConfigRevisionUpsertBulk struct {
	create *ConfigRevisionCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ConfigRevision.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(configrevision.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ConfigRevisionUpsertBulk) UpdateNewValues() *ConfigRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(configrevision.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(configrevision.FieldCreatedAt)
			}
			if _, exists := b.mutation.TeamID(); exists {
				s.SetIgnore(configrevision.FieldTeamID)
			}
			if _, exists := b.mutation.ConfigID(); exists {
				s.SetIgnore(configrevision.FieldConfigID)
			}
			if _, exists := b.mutation.Version(); exists {
				s.SetIgnore(configrevision.FieldVersion)
			}
			if _, exists := b.mutation.Builtin(); exists {
				s.SetIgnore(configrevision.FieldBuiltin)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(configrevision.FieldKind)
			}
			if _, exists := b.mutation.Name(); exists {
				s.SetIgnore(configrevision.FieldName)
			}
			if _, exists := b.mutation.Data(); exists {
				s.SetIgnore(configrevision.FieldData)
			}
			if _, exists := b.mutation.AuthorID(); exists {
				s.SetIgnore(configrevision.FieldAuthorID)
			}
			if _, exists := b.mutation.ReviewerID(); exists {
				s.SetIgnore(configrevision.FieldReviewerID)
			}
			if _, exists := b.mutation.Note(); exists {
				s.SetIgnore(configrevision.FieldNote)
			}
			if _, exists := b.mutation.Source(); exists {
				s.SetIgnore(configrevision.FieldSource)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.ConfigRevision.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *ConfigRevisionUpsertBulk) Ignore() *ConfigRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *ConfigRevisionUpsertBulk) DoNothing() *ConfigRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the ConfigRevisionCreateBulk.OnConflict
// documentation for more info.
func (u *ConfigRevisionUpsertBulk) Update(set func(*ConfigRevisionUpsert)) *ConfigRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ConfigRevisionUpsert{UpdateSet: update})
	}))
	return u
}

// Exec executes the query.
func (u *ConfigRevisionUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the ConfigRevisionCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for ConfigRevisionCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *ConfigRevisionUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
